yard=S(320,170,'The triangular back yard with sides 42 ft and 53 ft enclosing an angle of 135 degrees at A','<polygon points="30,60 290,25 130,140" fill="#bbf7d0" fill-opacity=".7" stroke="#166534" stroke-width="2.4"/>'+tx(12,60,'C')+tx(294,28,'B')+tx(125,158,'A')+tx(60,110,'42 ft')+tx(220,95,'53 ft')+tx(118,128,'135°',12))
def circ(case):
    r=80;cx,cy=110,100
    pt=lambda a:(cx+r*math.cos(math.radians(a)),cy-r*math.sin(math.radians(a)))
    if case==1:A,B,C,D=pt(125),pt(180),pt(300),pt(0)
    elif case==2:A,B,C,D=pt(110),pt(180),pt(30),pt(0)
    else:A,B,C,D=pt(90),pt(180),pt(0),None
    s=f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="#f8fafc" stroke="#475569" stroke-width="1.8"/><polygon points="{A[0]:.0f},{A[1]:.0f} {B[0]:.0f},{B[1]:.0f} {C[0]:.0f},{C[1]:.0f}" fill="#e0f2fe" fill-opacity=".5" stroke="#2563eb" stroke-width="2"/>'
    if D:s+=f'<path d="M{B[0]:.0f} {B[1]:.0f}L{D[0]:.0f} {D[1]:.0f}M{C[0]:.0f} {C[1]:.0f}L{D[0]:.0f} {D[1]:.0f}" stroke="#2563eb" stroke-width="1.8"/>'
    else:s+=f'<path d="M{B[0]:.0f} {B[1]:.0f}L{C[0]:.0f} {C[1]:.0f}" stroke="#2563eb" stroke-width="1.8"/>'
    s+=f'<circle cx="{cx}" cy="{cy}" r="2.5" fill="#dc2626"/>'+tx(A[0]-4,A[1]-8,'A')+tx(B[0]-16,B[1]+4,'B')+tx(C[0]+4,C[1]+16,'C')+tx(A[0]+4,A[1]+22,'α',13)
    if D:s+=tx(D[0]+6,D[1]+4,'D')
    s+=tx(cx+4,cy-6,'O')
    return S(230,215,f'Figure 11.20 ({"i" if case==1 else "ii" if case==2 else "iii"}): triangle ABC in its circumcircle',s)
